1	// Package optimizer implements adaptive optimization rules
2	package optimizer
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/profiler"
9	)
10	
11	// OptimizationRule defines a transformation rule
12	type OptimizationRule struct {
13		Name            string
14		TargetPattern   profiler.PatternKind
15		Priority        int
16		Description     string
17		Apply           func(*ast.Node) *ast.Node
18	}
19	
20	// ConstantFoldingRule evaluates constant expressions at compile time
21	var ConstantFoldingRule OptimizationRule
22	
23	func initConstantFoldingRule() {
24		ConstantFoldingRule = OptimizationRule{
25			Name:          "ConstantFolding",
26			TargetPattern: profiler.PatternConstantExpr,
27			Priority:      100,
28			Description:   "Evaluate constant expressions at compile time",
29			Apply: func(node *ast.Node) *ast.Node {
30				if node == nil {
31					return node
32				}
33	
34				// If it's a binary expression with two integer literals
35				if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
36					left, right := node.Children[0], node.Children[1]
37	
38					if left.Kind == ast.NodeIntLit && right.Kind == ast.NodeIntLit {
39						result := evaluateConstExpr(node)
40						if result != nil {
41							return result
42						}
43					}
44				}
45	
46				// Recursively apply to children
47				for i, child := range node.Children {
48					node.Children[i] = ConstantFoldingRule.Apply(child)
49				}
50	
51				return node
52			},
53		}
54	}
55	
56	// DeadCodeEliminationRule removes unused variable assignments
57	var DeadCodeEliminationRule OptimizationRule
58	
59	func initDeadCodeEliminationRule() {
60		DeadCodeEliminationRule = OptimizationRule{
61			Name:          "DeadCodeElimination",
62			TargetPattern: profiler.PatternDeadAssign,
63			Priority:      80,
64			Description:   "Remove unused variable assignments",
65			Apply: func(node *ast.Node) *ast.Node {
66				if node == nil {
67					return node
68				}
69	
70				// Mark dead assignments by filtering out declarations that are never read
71				// This would require dataflow analysis in a real implementation
72				// For now, just mark them with a comment
73	
74				for i, child := range node.Children {
75					node.Children[i] = DeadCodeEliminationRule.Apply(child)
76				}
77	
78				return node
79			},
80		}
81	}
82	
83	// InliningRule substitutes function calls with their body
84	var InliningRule OptimizationRule
85	
86	func initInliningRule() {
87		InliningRule = OptimizationRule{
88			Name:          "FunctionInlining",
89			TargetPattern: profiler.PatternInlinableCall,
90			Priority:      70,
91			Description:   "Inline simple function calls",
92			Apply: func(node *ast.Node) *ast.Node {
93				if node == nil {
94					return node
95				}
96	
97				// Function call inlining would require access to the program's function definitions
98				// This is a placeholder implementation
99	
100				for i, child := range node.Children {
101					node.Children[i] = InliningRule.Apply(child)
102				}
103	
104				return node
105			},
106		}
107	}
108	
109	// LoopInvariantMovementRule hoists loop-invariant expressions
110	var LoopInvariantMovementRule OptimizationRule
111	
112	func initLoopInvariantMovementRule() {
113		globalLicmCounter := 0 // 프로그램 전체에서 단조 증가하는 counter
114	
115		LoopInvariantMovementRule = OptimizationRule{
116			Name:          "LoopInvariantMovement",
117			TargetPattern: profiler.PatternLoopInvariant,
118			Priority:      101, // ConstantFolding(100) 보다 먼저 실행
119			Description:   "Move loop-invariant expressions outside loops",
120			Apply: func(node *ast.Node) *ast.Node {
121				if node == nil {
122					return node
123				}
124	
125				// 먼저 자식에 재귀 적용
126				for i, child := range node.Children {
127					node.Children[i] = LoopInvariantMovementRule.Apply(child)
128				}
129	
130				// for 루프 노드만 LICM 처리
131				if node.Kind != ast.NodeForStmt || len(node.Children) < 3 {
132					return node
133				}
134				body := node.Children[2]
135				if body.Kind != ast.NodeBlockStmt {
136					return node
137				}
138	
139				// 불변식 수집 및 본문 교체
140				var hoisted []*ast.Node
141				var newBody []*ast.Node
142	
143				for _, stmt := range body.Children {
144					if isInvariantLetDecl(stmt) {
145						licmName := fmt.Sprintf("__licm_%d", globalLicmCounter)
146						globalLicmCounter++
147	
148						// 호이스팅: let __licm_N = <원래 상수 식>
149						hoisted = append(hoisted, &ast.Node{
150							Kind:     ast.NodeLetDecl,
151							Line:     stmt.Line,
152							Col:      stmt.Col,
153							Children: []*ast.Node{
154								{Kind: ast.NodeIdent, Value: licmName},
155								stmt.Children[1],
156							},
157						})
158						// 루프 내부 교체: let x = __licm_N
159						newBody = append(newBody, &ast.Node{
160							Kind:     ast.NodeLetDecl,
161							Line:     stmt.Line,
162							Col:      stmt.Col,
163							Children: []*ast.Node{
164								stmt.Children[0],
165								{Kind: ast.NodeIdent, Value: licmName},
166							},
167						})
168					} else {
169						newBody = append(newBody, stmt)
170					}
171				}
172	
173				if len(hoisted) == 0 {
174					return node
175				}
176	
177				body.Children = newBody
178				// 루프 노드를 wrapper로 감싸기
179				wrapper := &ast.Node{Kind: ast.NodeBlockStmt, Line: node.Line, Col: node.Col}
180				wrapper.Children = append(hoisted, node)
181				return wrapper
182			},
183		}
184	}
185	
186	// CommonSubexpressionRule eliminates redundant computations
187	var CommonSubexpressionRule OptimizationRule
188	
189	func initCommonSubexpressionRule() {
190		CommonSubexpressionRule = OptimizationRule{
191			Name:          "CommonSubexpressionElimination",
192			TargetPattern: profiler.PatternRepeatedSubExpr,
193			Priority:      50,
194			Description:   "Cache results of repeated sub-expressions",
195			Apply: func(node *ast.Node) *ast.Node {
196				if node == nil {
197					return node
198				}
199	
200				for i, child := range node.Children {
201					node.Children[i] = CommonSubexpressionRule.Apply(child)
202				}
203	
204				return node
205			},
206		}
207	}
208	
209	// init initializes all rules
210	func init() {
211		initConstantFoldingRule()
212		initDeadCodeEliminationRule()
213		initInliningRule()
214		initLoopInvariantMovementRule()
215		initCommonSubexpressionRule()
216	}
217	
218	// evaluateConstExpr computes the result of a constant binary expression
219	func evaluateConstExpr(node *ast.Node) *ast.Node {
220		if node == nil || node.Kind != ast.NodeBinaryExpr {
221			return nil
222		}
223	
224		if len(node.Children) != 2 {
225			return nil
226		}
227	
228		left, right := node.Children[0], node.Children[1]
229		if left.Kind != ast.NodeIntLit || right.Kind != ast.NodeIntLit {
230			return nil
231		}
232	
233		leftVal := parseIntLiteral(left.Value)
234		rightVal := parseIntLiteral(right.Value)
235	
236		var result int64
237		switch node.Value {
238		case "+":
239			result = leftVal + rightVal
240		case "-":
241			result = leftVal - rightVal
242		case "*":
243			result = leftVal * rightVal
244		case "/":
245			if rightVal == 0 {
246				return nil // Don't fold division by zero
247			}
248			result = leftVal / rightVal
249		default:
250			return nil // Not a binary operator we can fold
251		}
252	
253		// Return a new constant node with the computed value
254		return &ast.Node{
255			Kind:  ast.NodeIntLit,
256			Value: formatInt(result),
257			Line:  node.Line,
258			Col:   node.Col,
259		}
260	}
261	
262	// parseIntLiteral converts a string to int64
263	func parseIntLiteral(s string) int64 {
264		var result int64
265		for _, c := range s {
266			if c >= '0' && c <= '9' {
267				result = result*10 + int64(c-'0')
268			}
269		}
270		return result
271	}
272	
273	// formatInt converts int64 back to string
274	func formatInt(n int64) string {
275		if n == 0 {
276			return "0"
277		}
278		var result string
279		neg := n < 0
280		if neg {
281			n = -n
282		}
283		for n > 0 {
284			result = string(byte(n%10)+'0') + result
285			n /= 10
286		}
287		if neg {
288			result = "-" + result
289		}
290		return result
291	}
292	
293	// DefaultRules returns all optimization rules in default order
294	func DefaultRules() []OptimizationRule {
295		return []OptimizationRule{
296			ConstantFoldingRule,
297			DeadCodeEliminationRule,
298			InliningRule,
299			LoopInvariantMovementRule,
300			CommonSubexpressionRule,
301		}
302	}
303	
304	// isInvariantLetDecl returns true if stmt is: let x = <const BinaryExpr>
305	func isInvariantLetDecl(stmt *ast.Node) bool {
306		if stmt == nil || stmt.Kind != ast.NodeLetDecl || len(stmt.Children) != 2 {
307			return false
308		}
309		val := stmt.Children[1]
310		return val != nil &&
311			val.Kind == ast.NodeBinaryExpr &&
312			len(val.Children) == 2 &&
313			val.Children[0].Kind == ast.NodeIntLit &&
314			val.Children[1].Kind == ast.NodeIntLit
315	}
