1	// Package ir implements IR generation from optimized AST
2	package ir
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8	)
9	
10	// Generator converts AST to intermediate representation
11	type Generator struct {
12		tempCount    int
13		labelCount   int
14		currentFn    *Function
15		program      *Program
16		structFields map[string][]string
17	}
18	
19	// NewGenerator creates a new IR generator
20	func NewGenerator() *Generator {
21		return &Generator{
22			tempCount:  0,
23			labelCount: 0,
24			program: &Program{
25				Functions: []Function{},
26				Main:      []Instruction{},
27			},
28			structFields: make(map[string][]string),
29		}
30	}
31	
32	// Generate converts an AST to an IR program
33	func (g *Generator) Generate(root *ast.Node) (*Program, error) {
34		if root == nil {
35			return g.program, nil
36		}
37	
38		// Process program statements
39		if root.Kind == ast.NodeProgram {
40			for _, child := range root.Children {
41				if child.Kind == ast.NodeFnDecl {
42					if err := g.genFnDecl(child); err != nil {
43						return nil, err
44					}
45				} else if child.Kind == ast.NodeStructDecl {
46					if err := g.genStructDecl(child); err != nil {
47						return nil, err
48					}
49				} else {
50					if err := g.genStmt(child); err != nil {
51						return nil, err
52					}
53				}
54			}
55		} else {
56			if err := g.genStmt(root); err != nil {
57				return nil, err
58			}
59		}
60	
61		return g.program, nil
62	}
63	
64	// genFnDecl generates IR for a function declaration
65	func (g *Generator) genFnDecl(node *ast.Node) error {
66		if len(node.Children) < 2 {
67			return fmt.Errorf("function declaration must have name and body")
68		}
69	
70		fnName := node.Children[0].Value
71		body := node.Children[len(node.Children)-1]
72	
73		fn := Function{
74			Name:   fnName,
75			Params: []string{},
76			Body:   []Instruction{},
77		}
78	
79		// Extract parameter names if they exist
80		if len(node.Children) > 2 {
81			for i := 1; i < len(node.Children)-1; i++ {
82				if node.Children[i].Kind == ast.NodeIdent {
83					fn.Params = append(fn.Params, node.Children[i].Value)
84				}
85			}
86		}
87	
88		// Save current function and switch context
89		prevFn := g.currentFn
90		g.currentFn = &fn
91	
92		// Generate OpEnter
93		g.emit(Instruction{Op: OpEnter, Fn: fnName})
94	
95		// Generate body
96		if body.Kind == ast.NodeBlockStmt {
97			for _, stmt := range body.Children {
98				if err := g.genStmt(stmt); err != nil {
99					return err
100				}
101			}
102		} else {
103			if err := g.genStmt(body); err != nil {
104				return err
105			}
106		}
107	
108		// Generate OpLeave if not already there
109		g.emit(Instruction{Op: OpLeave, Fn: fnName})
110	
111		// Add function to program
112		g.program.Functions = append(g.program.Functions, fn)
113		g.currentFn = prevFn
114	
115		return nil
116	}
117	
118	// genStmt generates IR for a statement
119	func (g *Generator) genStmt(node *ast.Node) error {
120		if node == nil {
121			return nil
122		}
123	
124		switch node.Kind {
125		case ast.NodeLetDecl:
126			return g.genLetDecl(node)
127		case ast.NodeIfStmt:
128			return g.genIfStmt(node)
129		case ast.NodeForStmt:
130			return g.genForStmt(node)
131		case ast.NodeReturn:
132			return g.genReturn(node)
133		case ast.NodeStructDecl:
134			return g.genStructDecl(node)
135		case ast.NodeBlockStmt:
136			for _, child := range node.Children {
137				if err := g.genStmt(child); err != nil {
138					return err
139				}
140			}
141			return nil
142		default:
143			// Expression statement
144			_, err := g.genExpr(node)
145			return err
146		}
147	}
148	
149	// genLetDecl generates IR for a let declaration
150	func (g *Generator) genLetDecl(node *ast.Node) error {
151		if len(node.Children) < 2 {
152			return fmt.Errorf("let declaration must have name and value")
153		}
154	
155		varName := node.Children[0].Value
156		valueExpr := node.Children[1]
157	
158		// Generate code for the expression
159		operand, err := g.genExpr(valueExpr)
160		if err != nil {
161			return err
162		}
163	
164		// Copy result to variable
165		g.emit(Instruction{
166			Op:   OpCopy,
167			Dest: Operand{Name: varName},
168			Src1: operand,
169		})
170	
171		return nil
172	}
173	
174	// genIfStmt generates IR for an if statement
175	func (g *Generator) genIfStmt(node *ast.Node) error {
176		if len(node.Children) < 2 {
177			return fmt.Errorf("if statement must have condition and body")
178		}
179	
180		condExpr := node.Children[0]
181		bodyStmt := node.Children[1]
182	
183		// Generate condition
184		condOp, err := g.genExpr(condExpr)
185		if err != nil {
186			return err
187		}
188	
189		// Create end label
190		endLabel := g.newLabel("end")
191	
192		// Jump if false
193		g.emit(Instruction{
194			Op:    OpJumpIfFalse,
195			Src1:  condOp,
196			Label: endLabel,
197		})
198	
199		// Generate body
200		if err := g.genStmt(bodyStmt); err != nil {
201			return err
202		}
203	
204		// Emit end label
205		g.emit(Instruction{
206			Op:    OpLabel,
207			Label: endLabel,
208		})
209	
210		return nil
211	}
212	
213	// genForStmt generates IR for a for statement
214	func (g *Generator) genForStmt(node *ast.Node) error {
215		if len(node.Children) < 3 {
216			return fmt.Errorf("for statement must have iterator, range, and body")
217		}
218	
219		iterName := node.Children[0].Value
220		rangeExpr := node.Children[1]
221		bodyStmt := node.Children[2]
222	
223		// Extract range start and end
224		if rangeExpr.Kind != ast.NodeBinaryExpr || rangeExpr.Value != ".." {
225			return fmt.Errorf("for loop requires range expression (..)")
226		}
227	
228		if len(rangeExpr.Children) < 2 {
229			return fmt.Errorf("range expression requires start and end")
230		}
231	
232		// 상수 범위 감지: 언롤링 시도
233		startNode := rangeExpr.Children[0]
234		endNode := rangeExpr.Children[1]
235		if sv, ok1 := isConstIntLit(startNode); ok1 {
236			if ev, ok2 := isConstIntLit(endNode); ok2 {
237				count := ev - sv
238				if count >= 0 && count <= loopUnrollThreshold {
239					return g.genUnrolledFor(iterName, sv, ev, bodyStmt)
240				}
241			}
242		}
243	
244		startOp, err := g.genExpr(rangeExpr.Children[0])
245		if err != nil {
246			return err
247		}
248	
249		endOp, err := g.genExpr(rangeExpr.Children[1])
250		if err != nil {
251			return err
252		}
253	
254		// Initialize iterator
255		g.emit(Instruction{
256			Op:   OpCopy,
257			Dest: Operand{Name: iterName},
258			Src1: startOp,
259		})
260	
261		// Create loop and end labels
262		loopLabel := g.newLabel("loop")
263		endLabel := g.newLabel("end")
264	
265		// Emit loop label
266		g.emit(Instruction{
267			Op:    OpLabel,
268			Label: loopLabel,
269		})
270	
271		// Check condition: iterator < end
272		cmpTemp := g.newTemp()
273		g.emit(Instruction{
274			Op:   OpLt,
275			Dest: cmpTemp,
276			Src1: Operand{Name: iterName},
277			Src2: endOp,
278		})
279	
280		// Jump if false (exit loop)
281		g.emit(Instruction{
282			Op:    OpJumpIfFalse,
283			Src1:  cmpTemp,
284			Label: endLabel,
285		})
286	
287		// Generate body
288		if err := g.genStmt(bodyStmt); err != nil {
289			return err
290		}
291	
292		// Increment iterator
293		incrTemp := g.newTemp()
294		g.emit(Instruction{
295			Op:   OpAdd,
296			Dest: incrTemp,
297			Src1: Operand{Name: iterName},
298			Src2: Operand{IsImm: true, ImmVal: 1},
299		})
300		g.emit(Instruction{
301			Op:   OpCopy,
302			Dest: Operand{Name: iterName},
303			Src1: incrTemp,
304		})
305	
306		// Jump back to loop
307		g.emit(Instruction{
308			Op:    OpJump,
309			Label: loopLabel,
310		})
311	
312		// Emit end label
313		g.emit(Instruction{
314			Op:    OpLabel,
315			Label: endLabel,
316		})
317	
318		return nil
319	}
320	
321	// genReturn generates IR for a return statement
322	func (g *Generator) genReturn(node *ast.Node) error {
323		if len(node.Children) == 0 {
324			g.emit(Instruction{Op: OpReturn})
325			return nil
326		}
327	
328		returnOp, err := g.genExpr(node.Children[0])
329		if err != nil {
330			return err
331		}
332	
333		g.emit(Instruction{
334			Op:   OpReturn,
335			Src1: returnOp,
336		})
337	
338		return nil
339	}
340	
341	// genExpr generates IR for an expression and returns the operand
342	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
343		if node == nil {
344			return Operand{}, fmt.Errorf("nil expression")
345		}
346	
347		switch node.Kind {
348		case ast.NodeIntLit:
349			// Parse integer literal
350			var val int64
351			fmt.Sscanf(node.Value, "%d", &val)
352			return Operand{IsImm: true, ImmVal: val}, nil
353	
354		case ast.NodeStringLit:
355			// String literal
356			return Operand{IsStr: true, SVal: node.Value}, nil
357	
358		case ast.NodeBoolLit:
359			// Boolean literal
360			return Operand{IsBool: true, BVal: node.Value == "true"}, nil
361	
362		case ast.NodeIdent:
363			return Operand{Name: node.Value}, nil
364	
365		case ast.NodeBinaryExpr:
366			return g.genBinaryExpr(node)
367	
368		case ast.NodeUnaryExpr:
369			return g.genUnaryExpr(node)
370	
371		case ast.NodeCallExpr:
372			return g.genCallExpr(node)
373	
374		case ast.NodeFieldAccess:
375			return g.genFieldAccess(node)
376	
377		case ast.NodeArrayLit:
378			return g.genArrayLit(node)
379	
380		case ast.NodeIndexExpr:
381			return g.genIndexExpr(node)
382	
383		default:
384			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
385		}
386	}
387	
388	// genBinaryExpr generates IR for a binary expression
389	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
390		if len(node.Children) < 2 {
391			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
392		}
393	
394		left, err := g.genExpr(node.Children[0])
395		if err != nil {
396			return Operand{}, err
397		}
398	
399		right, err := g.genExpr(node.Children[1])
400		if err != nil {
401			return Operand{}, err
402		}
403	
404		result := g.newTemp()
405		op := g.opcodeFromOp(node.Value)
406	
407		g.emit(Instruction{
408			Op:   op,
409			Dest: result,
410			Src1: left,
411			Src2: right,
412		})
413	
414		return result, nil
415	}
416	
417	// genUnaryExpr generates IR for a unary expression (!, -)
418	func (g *Generator) genUnaryExpr(node *ast.Node) (Operand, error) {
419		if len(node.Children) < 1 {
420			return Operand{}, fmt.Errorf("unary expression requires 1 operand")
421		}
422	
423		operand, err := g.genExpr(node.Children[0])
424		if err != nil {
425			return Operand{}, err
426		}
427	
428		result := g.newTemp()
429		op := node.Value
430	
431		switch op {
432		case "!":
433			// Logical NOT
434			g.emit(Instruction{
435				Op:   OpNot,
436				Dest: result,
437				Src1: operand,
438			})
439		case "-":
440			// Arithmetic negation: negate by subtracting from 0
441			g.emit(Instruction{
442				Op:   OpSub,
443				Dest: result,
444				Src1: Operand{IsImm: true, ImmVal: 0},
445				Src2: operand,
446			})
447		default:
448			return Operand{}, fmt.Errorf("unsupported unary operator: %s", op)
449		}
450	
451		return result, nil
452	}
