591	// genStructDecl generates IR for a struct declaration
592	func (g *Generator) genStructDecl(node *ast.Node) error {
593		if node.Value == "" {
594			return fmt.Errorf("struct declaration must have a name")
595		}
596	
597		name := node.Value
598		fields := []string{}
599	
600		// Extract field names from children
601		for _, field := range node.Children {
602			if field.Kind == ast.NodeFieldDecl {
603				fields = append(fields, field.Value)
604			}
605		}
606	
607		// Store struct definition
608		g.structFields[name] = fields
609	
610		// Calculate struct size (8 bytes per field)
611		size := len(fields) * 8
612	
613		// Save current function context
614		prevFn := g.currentFn
615		g.currentFn = nil // Emit to Main context
616	
617		// Emit OpStructDef instruction
618		g.emit(Instruction{
619			Op:   OpStructDef,
620			Fn:   name,
621			Src1: Operand{IsImm: true, ImmVal: int64(size)},
622		})
623	
624		// Restore function context
625		g.currentFn = prevFn
626	
627		return nil
628	}
629	
630	// genFieldAccess generates IR for a field access expression (obj.field)
631	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
632		if len(node.Children) == 0 {
633			return Operand{}, fmt.Errorf("field access requires object expression")
634		}
635	
636		// Generate IR for object expression
637		objOp, err := g.genExpr(node.Children[0])
638		if err != nil {
639			return Operand{}, err
640		}
641	
642		fieldName := node.Value
643	
644		// Search for field offset in known structs
645		var offset int64
646		found := false
647		for _, fields := range g.structFields {
648			for i, f := range fields {
649				if f == fieldName {
650					offset = int64(i * 8)
651					found = true
652					break
653				}
654			}
655			if found {
656				break
657			}
658		}
659		// If not found, use offset 0 as fallback
660	
661		// Emit OpFieldLoad instruction
662		result := g.newTemp()
663		g.emit(Instruction{
664			Op:   OpFieldLoad,
665			Dest: result,
666			Src1: objOp,
667			Src2: Operand{IsImm: true, ImmVal: offset},
668		})
669	
670		return result, nil
671	}
672	
673	// genArrayLit generates IR for array literals: [1, 2, 3]
674	func (g *Generator) genArrayLit(node *ast.Node) (Operand, error) {
675		// Generate IR for each element and emit as parameter
676		for _, elem := range node.Children {
677			op, err := g.genExpr(elem)
678			if err != nil {
679				return Operand{}, err
680			}
681			g.emit(Instruction{
682				Op:   OpParam,
683				Src1: op,
684			})
685		}
686	
687		// Create array with element count
688		result := g.newTemp()
689		g.emit(Instruction{
690			Op:   OpArrayNew,
691			Dest: result,
692			Src1: Operand{IsImm: true, ImmVal: int64(len(node.Children))},
693		})
694	
695		return result, nil
696	}
697	
698	// genIndexExpr generates IR for array indexing: arr[i]
699	func (g *Generator) genIndexExpr(node *ast.Node) (Operand, error) {
700		if len(node.Children) < 2 {
701			return Operand{}, fmt.Errorf("index expression requires array and index")
702		}
703	
704		arrOp, err := g.genExpr(node.Children[0])
705		if err != nil {
706			return Operand{}, err
707		}
708	
709		idxOp, err := g.genExpr(node.Children[1])
710		if err != nil {
711			return Operand{}, err
712		}
713	
714		result := g.newTemp()
715		g.emit(Instruction{
716			Op:   OpArrayLoad,
717			Dest: result,
718			Src1: arrOp,
719			Src2: idxOp,
720		})
721	
722		return result, nil
723	}
