1	// Package optimizer implements adaptive optimization selection
2	package optimizer
3	
4	import (
5		"sort"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/profiler"
9	)
10	
11	// AdaptiveOptimizer prioritizes optimization rules based on pattern frequency
12	type AdaptiveOptimizer struct {
13		rules []OptimizationRule
14	}
15	
16	// NewAdaptiveOptimizer creates a new optimizer with default rules
17	func NewAdaptiveOptimizer() *AdaptiveOptimizer {
18		return &AdaptiveOptimizer{
19			rules: DefaultRules(),
20		}
21	}
22	
23	// UpdatePriorities adjusts rule priorities based on pattern database
24	func (ao *AdaptiveOptimizer) UpdatePriorities(db *profiler.Database) {
25		// Get top patterns from database
26		topPatterns := db.TopPatterns(10)
27	
28		// Map pattern kind to rule indices
29		patternToRuleIndex := map[profiler.PatternKind]int{
30			profiler.PatternConstantExpr:      0, // ConstantFoldingRule
31			profiler.PatternDeadAssign:        1, // DeadCodeEliminationRule
32			profiler.PatternInlinableCall:     2, // InliningRule
33			profiler.PatternLoopInvariant:     3, // LoopInvariantMovementRule
34			profiler.PatternRepeatedSubExpr:   4, // CommonSubexpressionRule
35		}
36	
37		// Reset priorities to defaults
38		defaultRules := DefaultRules()
39		for i := range ao.rules {
40			ao.rules[i].Priority = defaultRules[i].Priority
41		}
42	
43		// Boost priorities for frequently seen patterns
44		for i, pattern := range topPatterns {
45			// Parse pattern kind from the entry
46			kind := parsePatternKind(pattern.Kind)
47			if ruleIdx, ok := patternToRuleIndex[kind]; ok && ruleIdx < len(ao.rules) {
48				// Priority boost: rank position * 10
49				boost := (10 - i) * 10
50				ao.rules[ruleIdx].Priority += boost
51			}
52		}
53	
54		// Sort rules by priority descending
55		sort.Slice(ao.rules, func(i, j int) bool {
56			return ao.rules[i].Priority > ao.rules[j].Priority
57		})
58	}
59	
60	// OptimizeAST applies optimization rules in priority order
61	func (ao *AdaptiveOptimizer) OptimizeAST(node *ast.Node) *ast.Node {
62		if node == nil {
63			return node
64		}
65	
66		// Apply each rule in priority order
67		for _, rule := range ao.rules {
68			node = rule.Apply(node)
69		}
70	
71		return node
72	}
73	
74	// OptimizeWithStats applies optimizations and returns statistics
75	func (ao *AdaptiveOptimizer) OptimizeWithStats(node *ast.Node) (*ast.Node, OptimizationStats) {
76		stats := OptimizationStats{
77			RulesApplied: []string{},
78		}
79	
80		if node == nil {
81			return node, stats
82		}
83	
84		// Apply each rule and track which rules actually changed something
85		for _, rule := range ao.rules {
86			before := nodeSignature(node)
87			node = rule.Apply(node)
88			after := nodeSignature(node)
89	
90			if before != after {
91				stats.RulesApplied = append(stats.RulesApplied, rule.Name)
92			}
93		}
94	
95		stats.NodeCount = countNodes(node)
96		return node, stats
97	}
98	
99	// OptimizationStats tracks the results of optimization
100	type OptimizationStats struct {
101		RulesApplied []string
102		NodeCount    int
103	}
104	
105	// parsePatternKind converts PatternEntry kind string back to PatternKind
106	func parsePatternKind(kindStr string) profiler.PatternKind {
107		switch kindStr {
108		case "ConstantExpr":
109			return profiler.PatternConstantExpr
110		case "DeadAssign":
111			return profiler.PatternDeadAssign
112		case "InlinableCall":
113			return profiler.PatternInlinableCall
114		case "LoopInvariant":
115			return profiler.PatternLoopInvariant
116		case "RepeatedSubExpr":
117			return profiler.PatternRepeatedSubExpr
118		default:
119			return 0
120		}
121	}
122	
123	// nodeSignature generates a quick hash of AST structure
124	func nodeSignature(node *ast.Node) string {
125		if node == nil {
126			return ""
127		}
128	
129		var sig string
130		sig += string(rune(node.Kind))
131		sig += "|" + node.Value
132		for _, child := range node.Children {
133			sig += "|" + nodeSignature(child)
134		}
135		return sig
136	}
137	
138	// countNodes returns the total number of nodes in the AST
139	func countNodes(node *ast.Node) int {
140		if node == nil {
141			return 0
142		}
143	
144		count := 1
145		for _, child := range node.Children {
146			count += countNodes(child)
147		}
148		return count
149	}
150	
151	// GetRules returns the current rule list
152	func (ao *AdaptiveOptimizer) GetRules() []OptimizationRule {
153		return ao.rules
154	}
155	
156	// GetRulePriorities returns all rules with their current priorities
157	func (ao *AdaptiveOptimizer) GetRulePriorities() map[string]int {
158		priorities := make(map[string]int)
159		for _, rule := range ao.rules {
160			priorities[rule.Name] = rule.Priority
161		}
162		return priorities
163	}
