10	// runProgram is a helper that parses code, generates IR, and runs the VM
11	func runProgram(t *testing.T, code string) (Value, map[string]Value) {
12		t.Helper()
13	
14		// Parse
15		p := parser.New(code)
16		prog, err := p.ParseProgram()
17		if err != nil {
18			t.Fatalf("parse error: %v", err)
19		}
20	
21		// Generate IR
22		gen := ir.NewGenerator()
23		irProg, err := gen.Generate(prog)
24		if err != nil {
25			t.Fatalf("IR gen error: %v", err)
26		}
27	
28		// Run VM
29		vm := New(irProg)
30		result, err := vm.Run()
31		if err != nil {
32			t.Fatalf("VM error: %v", err)
33		}
34	
35		return result, vm.DumpGlobals()
36	}
