18	// Value represents a runtime value in FreeLang
19	type Value struct {
20		Kind   ValueKind
21		IVal   int64             // for KindInt
22		BVal   bool              // for KindBool
23		SVal   string            // for KindString
24		Fields map[string]Value  // for KindStruct (keys: "f0", "f1", ...)
25		Elems  []Value           // for KindArray
26	}
27	
28	// Constructors
29	func NilVal() Value {
30		return Value{Kind: KindNil}
31	}
32	
33	func IntVal(n int64) Value {
34		return Value{Kind: KindInt, IVal: n}
35	}
36	
37	func BoolVal(b bool) Value {
38		return Value{Kind: KindBool, BVal: b}
39	}
40	
41	func StringVal(s string) Value {
42		return Value{Kind: KindString, SVal: s}
43	}
44	
45	func StructVal() Value {
46		return Value{Kind: KindStruct, Fields: make(map[string]Value)}
47	}
48	
49	func ArrayVal(elems []Value) Value {
50		return Value{Kind: KindArray, Elems: elems}
51	}
