53	// Truthy returns whether a value is truthy in a conditional context
54	func (v Value) Truthy() bool {
55		switch v.Kind {
56		case KindNil:
57			return false
58		case KindBool:
59			return v.BVal
60		case KindInt:
61			return v.IVal != 0
62		case KindString:
63			return v.SVal != ""
64		case KindArray:
65			return len(v.Elems) > 0
66		case KindStruct:
67			return len(v.Fields) > 0
68		default:
69			return true
70		}
71	}
72	
73	// String returns a human-readable representation
74	func (v Value) String() string {
75		switch v.Kind {
76		case KindNil:
77			return "nil"
78		case KindInt:
79			return fmt.Sprintf("%d", v.IVal)
80		case KindBool:
81			return fmt.Sprintf("%v", v.BVal)
82		case KindString:
83			return fmt.Sprintf("%q", v.SVal)
84		case KindArray:
85			result := "["
86			for i, e := range v.Elems {
87				if i > 0 {
88					result += ", "
89				}
90				result += e.String()
91			}
92			result += "]"
93			return result
94		case KindStruct:
95			return fmt.Sprintf("struct{%d fields}", len(v.Fields))
96		default:
97			return "unknown"
98		}
99	}
